/* ============================================================== 7 · results */

function sweepFigure(M) {
  const sweep = M.item_2_gradient.sweep;
  const w = 660;
  const h = 300;
  const padL = 54;
  const padB = 46;
  const padT = 34;
  const padR = 20;

  const digits = sweep.map((r) => (r.matching_digits === null ? 16 : r.matching_digits));
  /* The axis spans the data with a margin, not 0..max. Anchoring at zero left the lower half of
   * the chart empty and flattened the very shape the figure exists to show — and this is a count
   * of matching digits, where zero is not a meaningful baseline anyone reads against. */
  const lo = Math.floor(Math.min(...digits)) - 1;
  const hi = Math.ceil(Math.max(...digits)) + 1;
  const x = (i) => padL + (i / (sweep.length - 1)) * (w - padL - padR);
  const y = (v) => padT + ((hi - v) / (hi - lo)) * (h - padT - padB);

  const node = svg('svg', {
    viewBox: `0 0 ${w} ${h}`,
    class: 'fig sweepfig',
    role: 'img',
    'aria-label':
      'Matching decimal digits against nudge size: agreement rises, peaks, then falls again',
  });

  for (let g = 0; g <= 4; g += 1) {
    const v = lo + ((hi - lo) * g) / 4;
    node.append(
      svg('line', { x1: padL, x2: w - padR, y1: y(v), y2: y(v), class: 'gridline' }),
      svgText(padL - 10, y(v) + 4, 'axis end', v.toFixed(0))
    );
  }
  node.append(svgText(padL - 10, padT - 4, 'axis end', 'digits'));

  const d = digits.map((v, i) => `${i ? 'L' : 'M'} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');
  node.append(svg('path', { d, class: 'sweep-line' }));

  const best = digits.indexOf(Math.max(...digits));
  digits.forEach((v, i) => {
    node.append(
      svg('circle', { cx: x(i), cy: y(v), r: i === best ? 6 : 4, class: i === best ? 'dot best' : 'dot' })
    );
    node.append(svgText(x(i), h - padB + 20, 'axis mid', `1e${Math.round(Math.log10(sweep[i].epsilon))}`));
  });
  node.append(svgText(w / 2, h - 8, 'axis mid', 'nudge size'));
  /* Above the point, but inside the padding reserved for it — the first version put it 16px above
   * a peak that was already at the top of the plot, and it rendered clipped by the viewBox. */
  node.append(
    svgText(x(best), Math.max(y(digits[best]) - 16, 16), 'sweep-lab mid',
      `${digits[best].toFixed(1)} digits`)
  );
  node.append(svgText(padL + 4, y(digits[0]) + 22, 'sweep-side', 'too big: a straight line across a curve'));
  node.append(
    svgText(w - padR - 4, y(digits[digits.length - 1]) + 22, 'sweep-side end', 'too small: rounding noise')
  );

  return node;
}

function chapterResults(M) {
  const two = M.item_2_gradient;
  const three = M.item_3_accumulation;
  const four = M.item_4_grad_norm;
  const five = M.item_5_mfu;
  const six = M.item_6_floats;
  const curves = three.curves;

  const s = section(
    'results',
    'results',
    'The ledger',
    `${Spell(Object.keys(M).filter((k) => k.startsWith('item_')).length)} numbers, and what each of them counts`,
    [
      `Every figure below is read from <code>results/run.json</code>. Nothing on this page is typed,
       and a test regenerates the page's data and fails if the tracked copy differs.`,
    ],
    { short: 'The ledger', sub: 'every number, and what it counts' }
  );

  s.append(
    figure(
      sweepFigure(M),
      2,
      `<b>The shape is the finding, not the peak.</b> A hand-computed derivative draws a straight
       line across a curve — the wider you draw it the less it matches — so agreement improves as
       the nudge shrinks. Then it gets <i>worse</i>, because the two losses being subtracted stop
       differing in bits the float type keeps. There is a <b>window</b>, not a best value, and a
       check that agreed at exactly one nudge size would have been fitted rather than verified.`
    )
  );

  s.append(
    table(
      ['measurement', 'result'],
      [
        {
          cells: [
            '1 · every shape in the step',
            'the loss has <b>no dimensions at all</b> — which is why a mistake anywhere before it changes training without changing a shape',
          ],
        },
        {
          cells: [
            '2 · one gradient, by hand',
            `autograd <b>${two.analytic.toFixed(9)}</b> against <b>${two.numeric.toFixed(9)}</b> — ${two.best_matching_digits.toFixed(1)} matching digits`,
          ],
        },
        {
          cells: [
            '3 · accumulation, broken',
            `<b>${three.correct.toFixed(4)}</b> correct against <b>${three.wrong.toFixed(4)}</b> wrong — ${pct(three.relative_gap)} out`,
          ],
        },
        {
          cells: [
            '4 · the grad norm leading',
            `<b>${four.count}</b> of ${int(M.facts.steps)} steps qualify`,
          ],
          __mark: 'warn',
        },
        {
          cells: [
            '5 · utilisation',
            `<b>${pct(five.mfu, 2)}</b> of ${(five.device_peak_flops / 1e12).toFixed(3)} TFLOP/s measured on this machine`,
          ],
        },
        {
          cells: [
            '6 · 0.1 in three formats',
            `fp32 <code>${six.fp32.hex}</code> · bf16 <code>${six.bf16.hex}</code> · fp8 E4M3 <code>${six['fp8 E4M3'].hex}</code>`,
          ],
        },
      ]
    )
  );

  const acc = el('p', 'say');
  acc.innerHTML = `<b>And the same two reductions driving a real run.</b> Over
    ${int(curves.total_steps)} steps, everything held identical but the reduction, the wrong one
    ends ${signed(curves.final_gap)} away. But the sign is not constant — it reads lower at
    <b>${curves.steps_where_wrong_read_lower}</b> of those steps — so the signed mean
    (${signed(curves.mean_signed_gap)}) is the number that carries a direction, and the endpoint
    alone would be whichever step the run happened to stop on.`;
  s.append(acc);

  const norm = el('p', 'say');
  norm.innerHTML = `<b>The gradient-norm result is the weakest thing on this page and is reported
    that way.</b> A step qualifies only if the norm moved sharply, the loss did not, <i>and</i> the
    loss then followed — the third condition is what makes it a claim about <i>before</i> rather
    than a same-step size comparison. ${four.count} of ${int(M.facts.steps)} steps clear that bar,
    and at the strictest threshold none do.`;
  s.append(norm);
}

/* ============================================================== 8 · negatives */

function chapterNegatives(M) {
  const five = M.item_5_mfu;
  const rows = auditRows(M);
  const s = section(
    'negatives',
    'negatives',
    'The audit trail',
    `${Spell(rows.length)} numbers as first published, and what each became`,
    [
      `<b>Not one of these was caught by a failing test</b>, and not one was a miscalculation. Each
       was arithmetic anyone could check, answering a question nobody had asked out loud — and each
       was found by asking that question, which is the only technique this page has to offer.`,
      `They are laid out as an audit trail rather than as a list of regrets: the figure as it was
       published, and the figure it became. <b>The gap between the two columns is the whole
       argument</b>, because a reader who only ever sees the right-hand one has no way to judge how
       far a confident, wrong number can travel.`,
    ],
    { short: 'The audit trail', sub: 'as first published, then corrected' }
  );

  s.append(
    table(
      ['as first published', 'the question asked of it', 'what it became'],
      rows,
      'grid prose'
    )
  );
  auditTail(M, s);
}

/** The corrections, as data, so the section that introduces them can count them. */
function auditRows(M) {
  const five = M.item_5_mfu;
  const fp8 = M.item_6_floats.regression['fp8 E4M3'];
  const bf16 = M.item_6_floats.regression.bf16;
  return [
        {
          cells: [
            '<b>0.1 decomposes correctly</b> — the only value the test drove',
            'What does it do on every other value?',
            `An overflow flag computed from the <i>value's</i> field width rather than a fixed one
             returned numbers <b>exactly twice too large</b> on
             <b>${pct(fp8.doubled_rate)}</b> of fp8 inputs and ${pct(bf16.doubled_rate)} of bf16,
             and <i>raised</i> on a further ${pct(fp8.raised_rate)} and ${pct(bf16.raised_rate)}.
             0.1 is one of the values where the flag cannot fire. <b>Those rates were themselves
             folklore until this run</b>: the page quoted a single 30% that merged the two, from a
             figure that lived in a Python docstring and was recomputed by nothing.`,
          ],
          __mark: 'bad',
        },
        {
          cells: [
            '<b>39.13%</b> utilisation, which looked excellent',
            'Which machine is the denominator?',
            `A different one. The numerator was measured on the CPU and the denominator was a GPU's
             advertised peak — two right numbers about different processors. The peak is measured
             now, on the same device and dtype as the run, which reports a <i>worse</i> figure:
             <b>${pct(five.mfu, 2)}</b>. Both halves are bound to one device constant, so they can
             no longer disagree, and the device is recorded beside the result.`,
          ],
          __mark: 'bad',
        },
        {
          cells: [
            'The same figure, counting every parameter in the model',
            'Which of them actually do arithmetic?',
            `Not the embedding tables — a lookup is a gather. Counting them made the numerator
             <b>${pct(M.facts.parameters / M.facts.non_embedding_parameters - 1, 0)} larger than it
             should have been</b>; equivalently, removing them cut it by
             ${pct(1 - M.facts.non_embedding_parameters / M.facts.parameters, 0)}. Both describe one
             correction, and quoting the wrong member of that pair is itself a right number
             answering a different question.`,
          ],
          __mark: 'bad',
        },
        {
          cells: [
            '<b>Nine steps</b> where the gradient led the loss',
            'Led it, or merely moved more than it?',
            `The second. "The gradient moved <i>before</i> the loss" was measured as "the gradient
             moved a lot and the loss moved a little, <i>at the same step</i>" — a size comparison
             wearing a claim about time. Requiring the loss to actually follow cut the count to
             one.`,
          ],
        },
        {
          cells: [
            'Two guards, green, over the bugs they were written for',
            'Could either of them have failed?',
            `Neither. One asserted the accumulation gap's <i>direction</i> at six steps, where the
             sign is negative several times — a coin flip that landed right. The other checked a
             utilisation ceiling against a made-up numerator orders of magnitude below any plausible
             peak, so it could not have failed on the 39.13% defect it existed to catch.`,
          ],
        },
        {
          cells: [
            'Every number here, with nothing saying where it came from',
            'Which code, which machine, which text?',
            `<code>run.json</code> carried <b>no provenance at all</b> — six published figures and a
             ${int(M.facts.steps)}-step trace, saying nothing. The corpus was a sentence rather than
             a digest, because this exercise imported exercise 09's <i>private</i> corpus builder
             and not its public accounting. Six fields now, and the writer refuses without them.`,
          ],
          __mark: 'bad',
        },
      ];
}

/** The paragraph that follows the audit table, kept beside it rather than inside the row data. */
function auditTail(M, s) {
  const note = el('p', 'say');
  note.innerHTML = `<b>Read the middle column on its own.</b> Every question in it is the same
    question in different clothes — <i>what is this number actually counting?</i> — and not one of
    them needs any knowledge of this exercise to ask. That is the transferable part; the specific
    arithmetic is not.`;
  s.append(note);
}

/* ============================================================== 9 · conclusion */

function chapterConclusion(M) {
  const s = section(
    'conclusion',
    'conclusion',
    'The verdict',
    'Ask what each half of a ratio is counting',
    [
      `Every correction on this page came from the same question, asked about a different number.
       Not "is this arithmetic right" — it was, every time — but <b>"is this quantity the one the
       sentence claims"</b>.`,
      `A wrong number gets caught by a reader. A right number answering an adjacent question does
       not, and it is more convincing precisely <i>because</i> the arithmetic checks out.`,
    ],
    { short: 'The verdict', sub: 'ask what the number counts' }
  );

  const box = el('div', 'takeaway');
  box.innerHTML = `<b>The cheapest version of this check.</b> Before quoting a derived figure, say
    out loud what question it answers — then check that it is the question you asked. Utilisation
    of <i>what</i>, on <i>which</i> machine, over <i>which</i> parameters. A decomposition verified
    at how <i>many</i> values. A gradient that moved before the loss, or merely more than it.`;
  s.append(box);
}

/* ============================================================== 10 · limits */

function chapterLimits(M) {
  const five = M.item_5_mfu;
  /* Built before the section, so the heading counts the list rather than claiming a
   * number for it. It read "Five things this page does not show" as a literal. */
  const items = [
    `<b>Nothing about whether the model is any good.</b> Every item measures the loop, not what it
     produced. The losses are incidental.`,
    `<b>${pct(five.mfu, 2)} on a laptop CPU in fp32 is not utilisation on training hardware</b>, and
     comparing it to a published bf16 figure would compare two different quantities.`,
    `<b>The FLOPs estimate is a convention.</b> It excludes attention's quadratic term and treats
     every non-embedding parameter as two forward and four backward operations per token.`,
    `<b>The gradient check verifies one weight</b> — the one with the largest gradient in the head.
     It is evidence about autograd <i>there</i>, not a proof about the whole graph.`,
    `<b>The leading-step count is one reading of an arbitrary threshold.</b> The count at four other
     thresholds is published beside it for exactly that reason, and at the strictest one it is zero.`,
  ];

  const s = section(
    'limits',
    'limits',
    'In the open',
    `${Spell(items.length)} things this page does not show`,
    [
      `In the open text rather than behind a disclosure, because a limitation a reader has to expand
       is a limitation the page is hiding.`,
    ],
    { short: 'The limits', sub: 'what one laptop run cannot settle' }
  );

  const ul = el('ul', 'limits');
  for (const item of items) {
    const li = el('li');
    li.innerHTML = item;
    ul.append(li);
  }
  s.append(ul);
}

/* ============================================================== 11 · next */

function chapterNext() {
  const s = section(
    'next',
    'next',
    'The next number to distrust',
    'What a real run needs that this does not have',
    [
      `Everything here fits on one machine and finishes in half a minute. Three things change when
       neither is true.`,
    ],
    { short: 'What this opens', sub: 'what a real run adds' }
  );

  const ul = el('ul', 'limits');
  for (const item of [
    `<b>bf16, and the reason it won.</b> It keeps fp32's eight exponent bits and spends the whole
     saving out of the mantissa — so a gradient that would underflow to zero in fp16 survives, and
     none of fp16's loss-scaling machinery is needed. Gradient descent tolerates imprecision far
     better than it tolerates zeros.`,
    `<b>Sixteen bytes per weight, not four.</b> A finished model needs its weights; training one
     needs the weights, their gradients, a full-precision copy, and the optimiser's two running
     numbers. That arithmetic is why one accelerator stops being enough sooner than most people
     expect.`,
    `<b>Telemetry that survives weeks.</b> A trace worth keeping is one where a spike three days in
     can be traced to the batch that caused it — which the grad-norm log here is the smallest
     possible version of.`,
  ]) {
    const li = el('li');
    li.innerHTML = item;
    ul.append(li);
  }
  s.append(ul);
}

/* ============================================================== 12 · reproduce */

/* This was a shell transcript headed "Two commands" over three of them, promising a regeneration
 * test that did not exist. The test exists now -- it was cheaper to make the claim true than to
 * delete it -- and the commands have moved to the README, beside the code they run. What a stranger
 * needs in order to check a figure is not the command that produced it; anybody can type a command.
 * It is knowing which code, which text and which machine answered. */
function chapterReproduce(M) {
  const prov = M.provenance;
  const corpus = M.facts.corpus;
  const env = prov.environment;
  const rows = [
    ['which settings', `<code>${prov.config_fingerprint}</code>`, 'every field of the configuration, hashed'],
    [
      'which code',
      `<code>${prov.code_digest.slice(0, 19)}…</code>`,
      'this exercise <b>and</b> exercise 09, whose losses these timings are of',
    ],
    ['which commit', `<code>${prov.git_sha.slice(0, 12)}</code>`, 'the tree it ran from'],
    [
      'which text',
      `<code>${prov.corpus_digest.slice(0, 19)}…</code>`,
      `${int(corpus.corpus_tokens)} tokens, read ${corpus.epochs.toFixed(2)} times over`,
    ],
    ['which vocabulary', `<code>${prov.tokenizer_digest.slice(0, 19)}…</code>`, "exercise 02's frozen BPE"],
    [
      'which machine',
      `${env.platform.split('-').slice(0, 2).join(' ')} · ${env.device}`,
      `python ${env.python} · torch ${env.torch} · ${env.torch_threads} threads`,
    ],
  ];

  const s = section(
    'reproduce',
    'reproduce',
    'Every figure and its parent',
    `${Spell(rows.length)} things that had to be recorded for any of this to be checkable`,
    [
      `A number nobody can regenerate is not evidence, it is folklore. Every figure on this page is
       read from one tracked file, and that file carries the block below. Writing it without them
       <b>raises</b>; it does not warn.`,
      `<b>The machine is not context here, it is an input.</b> Every headline on this page is a
       throughput number, and utilisation is a ratio whose two halves must come from the same
       processor — which is the mistake the <a href="#negatives">audit trail</a> opens with.
       Recording the device is what turns "these numbers differ" from a mystery into a fact about
       where they were produced.`,
    ],
    { short: 'The index', sub: 'what produced every number here' }
  );

  s.append(
    table(
      ['question', 'answer', 'what it covers'],
      rows.map((r) => ({ cells: [r[0], r[1], r[2]] })),
      'grid'
    )
  );

  const p = el('p', 'say small');
  p.innerHTML = `Digests are shown truncated to fit; the file carries them at full length, which is
    the point — a prefix cannot be checked. The commands that regenerate all of this are in the
    repository's own README, beside the code they run.
    <a href="https://github.com/pankajkr23/llm-pretraining-exercises/tree/main/src/exercises/10-training-loop">Code,
    tests and the full write-up</a>.`;
  s.append(p);
}

/* ============================================================== rail + footer */

function buildRail(root) {
  const rail = document.getElementById('rail');
  if (!rail) return;
  rail.replaceChildren();
  const inner = el('div', 'rail-inner');
  const head = el('div', 'rail-head');
  head.append(el('div', 'rail-title', 'On this page'));
  inner.append(head);
  const list = el('div', 'rail-list');
  const links = new Map();
  for (const sec of root.querySelectorAll('section')) {
    if (!sec.dataset.title) continue;
    const link = el('a', 'rail-link');
    link.href = `#${sec.id}`;
    const body = el('span', 'rail-body');
    body.append(el('span', 'rail-t', sec.dataset.title));
    if (sec.dataset.sub) body.append(el('span', 'rail-sub', sec.dataset.sub));
    link.append(el('span', 'rail-n', sec.dataset.n), body);
    list.append(link);
    links.set(sec.id, link);
  }
  inner.append(list);
  rail.append(inner);
  markPosition(root, links);
}

/* Registered from the code that has already appended the sections: an IntersectionObserver on a
 * detached node never fires and reports nothing, which is how three of exercise 08's plates
 * shipped without ever animating. */
function markPosition(root, links) {
  const sections = [...root.querySelectorAll('section')].filter((s) => links.has(s.id));
  if (!sections.length || typeof IntersectionObserver !== 'function') return;

  const visible = new Set();
  const observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) visible.add(entry.target.id);
        else visible.delete(entry.target.id);
      }
      const current = sections.find((s) => visible.has(s.id));
      for (const [id, link] of links) {
        link.classList.toggle('on', Boolean(current) && id === current.id);
      }
    },
    { rootMargin: '-10% 0px -70% 0px', threshold: 0 }
  );
  for (const s of sections) observer.observe(s);
}

function buildFooter() {
  const f = document.getElementById('foot');
  if (!f) return;
  const p = el('p', 'say small');
  p.innerHTML =
    'Written for whoever arrives first: the argument is in plain words, and every number behind it ' +
    'is two commands away. ' +
    '<a href="https://github.com/pankajkr23/llm-pretraining-exercises/tree/main/src/exercises/10-training-loop">Code, tests and the full write-up</a>.';
  f.append(p);
}

export function buildPage(M) {
  chapterThesis(M);
  chapterGlossary(M);
  chapterProblem();
  chapterMechanism(M);
  chapterMethod(M);
  chapterExpected(M);
  chapterResults(M);
  chapterNegatives(M);
  chapterConclusion(M);
  chapterLimits(M);
  chapterNext();
  chapterReproduce(M);
  buildRail(main());
  buildFooter();
}
